/* ── A csapat ── */
const TEAMK=[['alvas','Most figyeli: a késői vacsorákat és az éjszakádat.',72,'1 kérdés vár rád'],['mozgas','Most figyeli: a terhelésedet. Egy sejtésen dolgozik.',60,''],['etkezes','Most figyeli: a vacsoraidődet. Egy kísérlete fut.',80,'kísérlet fut'],['kozerzet','Kevés az adata: ma kért tőled egy bejelentkezést.',30,'kevés adat'],['mezo','A vasárnapi konzíliumon 2 dolog került a közös képbe.',66,'']];
function csapat(){const best=[...TEAMK].sort((a,b)=>b[2]-a[2])[0],low=[...TEAMK].sort((a,b)=>a[2]-b[2])[0];
  return `${phead('A csapat',{ph:'mezo-asztal.jpg',eb:'Öten figyelnek rád',title:`Az ${nm(best[0])} ismer a legjobban`,sub:`A ${nm(low[0])} még keveset tud rólad.`,btn:`${G('check','ink')}Bejelentkezem · 1 perc`,attrs:'data-sheet="napCheckin"',tabs:MZTABS})}
  <h1 class="head rise" style="--i:1">Öt figyelő, egy közös kép rólad. <em>A Közérzet</em> kér tőled a legtöbbet.</h1><p class="lead rise" style="--i:1">Egy esti bejelentkezés neki egy hétnyi tanulás.</p>
  <section class="sec rise first" style="--i:2"><div class="sh"><h3>Mennyire ismernek</h3><span class="crumb">a képük érettsége</span></div><div class="card deep pre"><div class="mwfive">${TEAMK.map(([k,,p])=>`<button class="${p<40?'low':''}" data-go="mezo-tag-${k}" aria-label="${nm(k)}: ${p}%"><span class="tb"><i style="--h:${p}%"></i>${G(TM[k][1],'cream')}</span><b>${p}</b><small>${nm(k)}</small></button>`).join('')}</div></div></section>
  <section class="sec rise" style="--i:3"><div class="sh"><h3>A csapat tagjai</h3></div><div style="display:grid;gap:12px">${TEAMK.map(([k,t,p,c])=>`<article class="card mwm"><div class="hd">${bd(k)}<div><b>${nm(k)}</b><small>${TM[k][3]}</small></div>${c?`<span class="chip ${/vár|kevés/.test(c)?'warm':'soft'}">${c}</span>`:''}</div><p>${t}</p><div class="lv"><u><i style="--w:${p}%;${p<40?'background:var(--peach)':''}"></i></u><b>${p}%</b><small>ennyire érett a képe rólad</small></div><button class="pill soft" data-go="mezo-tag-${k}">Az oldala</button></article>`).join('')}
    <article class="card mwm"><div class="hd">${bd('szk')}<div><b>Szkeptikus</b><small>a csapat kételkedője</small></div><span class="chip">nem posztol</span></div><p>A beszélgetésekben kérdez vissza, mielőtt bármi bekerülne rólad. Legutóbb a vacsora-ügyben szólt közbe.</p><button class="pill soft" data-go="mezo-poszt-vacsora">Ahol legutóbb szólt</button></article></div></section>
  <section class="sec rise" style="--i:4"><div class="sh"><h3>A közös munka</h3></div><div class="dlist one">${[['nap-baratok','Beszélgess Mezóval','emlékszik, és jelzi','mezo-chat'],['mezo-asztal','Konzílium','a heti ülés · +2 rólad','mezo-konzilium'],['mezo-nagyito','Kérdezd meg a csapatot','2 korábbi válasz','mezo-kerdezd'],['nap-seta','Coaching','a mai kártya','mezo-coaching'],['mezo-labor','Minták, előrejelzések, kísérletek','17 minta · 1 kísérlet','mezo-mintak'],['mezo-gep','Gépterem','adatforrások, futások, figyelők','mezo-gepterem']].map(([p,t,s,g])=>`<article class="dl tap" role="button" tabindex="0" data-go="${g}"><span class="stk"><img src="${PH(p+'-sq.jpg')}" alt=""></span><div class="dtx"><strong>${t}</strong><div class="chips"><span class="chip">${s}</span></div></div>${G('chev','ink','chev')}</article>`).join('')}</div></section>
  ${mzCard('A csapat nem dönt helyetted. <em>Javasol, megmutatja, miből látja</em>, és megkérdez.')}</div>`}
/* ── a member's page ── */
const TAG={alvas:{q:'„Hétvégén átlag 40 perccel később fekszel le, és ezt a hétfőd megérzi.”',c:[30,38,45,51,58,63,68,72],work:[['Rád vár','A késői vacsora és az éjszakád','mezo-poszt-vacsora','warm'],['Gyűlik','A 23:05-ös lefekvés sorozat · 2 / 3','mezo-poszt-gyors',''],['Bekerült','A hétvégi lefekvés-minta','mezo-poszt-hetvege','soft']],facts:[['Hétköznap 23:00 körül fekszel','23× visszaigazolva'],['A koffein 14 óra után már nem','12× visszaigazolva'],['Edzés után később alszol el','8× · még erősödik']],closed:[['A délutáni alvás nem segít','szeptember 2. · elvetetted'],['A meleg szoba rontja az alvást','augusztus 20. · bekerült']],req:'Ma este <em>22:45-kor</em> szólok. Ha sikerül, a hármas sorozat a minta kezdete.'},
  mozgas:{q:'„A röpi utáni napokon nehezebb a húzás. Ezt figyelembe veszem a tervben.”',c:[20,28,35,41,47,52,57,60],work:[['Gyűlik','Egyhangúbb hetek után esik az energiád? · 5 / 8','mezo-poszt-sejtes',''],['Kísérlet','Szénhidrát a meccs előtt · 4 / 7','mezo-poszt-kiserlet','soft']],facts:[['A váll a röpi után 6 / 10','9× visszaigazolva'],['A súlyozott húzódzkodás a legjobb gyakorlatod','2 rekord a hónapban']],closed:[['Jó alvás után könnyebb edzés','vasárnap · nem jött be']],req:'Jövő héten egy <em>változatosabb blokkot</em> javaslok: ebből tanulok a legtöbbet.'},
  etkezes:{q:'„A fehérje megy. A délutáni zöldség marad el, ott tudok segíteni.”',c:[35,44,52,60,66,72,77,80],work:[['Döntés','Többet iszol, több az energiád?','mezo-poszt-viz','warm'],['Kísérlet','Szénhidrát a meccs előtt','mezo-poszt-kiserlet','soft']],facts:[['Reggel 7:30 körül eszel','30× visszaigazolva'],['A túró a kedvenc uzsonnád','14× visszaigazolva'],['20:30 után vacsorázol szerdánként','6× · még erősödik']],closed:[['A késő esti szénhidrát rontja az alvást','szeptember 12. · elvetettük']],req:'Holnap <em>délutáni falatokat</em> hozok: zöldség, ami tényleg elfogy.'},
  kozerzet:{q:'„Két hétből csak négy estéről tudom, hogy érezted magad.”',c:[5,8,12,15,19,23,27,30],work:[['Kérés','Egy perc bejelentkezés ma este','mezo-poszt-kozerzet','warm']],facts:[['Délután feszültebb vagy','4× · még kevés']],closed:[],req:'Egy perc ma este, és <em>hétvégére</em> megmutatom, mi mozgatja az energiádat.'},
  mezo:{q:'„Én fogom össze a csapatot. Vasárnap két dolog került a közös képbe.”',c:[20,30,38,45,52,58,62,66],work:[['Bekerült','A hétvégi lefekvés-minta','mezo-poszt-hetvege','soft'],['Konzílium','A heti ülés jegyzőkönyve','mezo-konzilium','']],facts:[['Este 21:00-kor olvasod az összegzést','18× visszaigazolva'],['A hosszú üzeneteket nem szereted','te mondtad']],closed:[['Napi két értesítés elég','szeptember 1. · beállítva']],req:'Este 21:00-kor jön a <em>napi összegzés</em>. Ha sok, szólj, és ritkítom.'}};
const TS={mute:{}};
function tag(k){const T=TAG[k],[n,ic,pal,area,ph]=TM[k],mx=Math.max(...T.c),W=320,H=110,X=i=>14+i*(W-28)/7,Y=v=>H-12-v/100*(H-28),path=T.c.map((v,i)=>`${i?'L':'M'}${X(i).toFixed(1)} ${Y(v).toFixed(1)}`).join(' ');
  return `${ihead({ph:ph+'.jpg',crumb:`Mezo › A csapat › <b>${n}</b>`,eb:`${n} · ${area}`,title:`${T.c[7]}%-ban ismer`,sub:'nyolc hét alatt ennyire érett a képe rólad'})}
  <section class="sec rise first" style="--i:2"><div class="card mwq t-sun">${T.q}<small>${n}</small></div></section>
  <section class="sec rise" style="--i:3"><div class="sh"><h3>Ahogy megismert</h3><span class="crumb">8 hét</span></div><div class="card deep" style="padding:14px"><svg class="mwcurve" viewBox="0 0 ${W} ${H}" role="img" aria-label="${n} képének érettsége nyolc hét alatt" data-scrub='${JSON.stringify(T.c.map((v,i)=>[X(i)/W,`${i+1}. hét · ${v}%`]))}'><path d="${path} L${X(7)} ${H} L${X(0)} ${H} Z" fill="rgba(168,213,186,.22)"/><path d="${path}" fill="none" stroke="#A8D5BA" stroke-width="3" stroke-linecap="round"/>${T.c.map((v,i)=>`<circle cx="${X(i)}" cy="${Y(v)}" r="${i===7?6:3.5}" fill="${i===7?'#fff':'#A8D5BA'}"/>`).join('')}</svg></div></section>
  <section class="sec rise" style="--i:4"><div class="sh"><h3>Most ezen dolgozik</h3></div><div class="dlist one">${T.work.map(([s,t,g,c])=>`<article class="dl tap" role="button" tabindex="0" data-go="${g}"><span class="stk"><img src="${PH(ph+'-sq.jpg')}" alt=""></span><div class="dtx"><strong>${t}</strong><div class="chips"><span class="chip ${c}">${s}</span></div></div>${G('chev','ink','chev')}</article>`).join('')}</div></section>
  <section class="sec rise" style="--i:5"><div class="sh"><h3>Amit tud rólad</h3><span class="crumb">${T.facts.length} tény</span></div><div class="card pad mwfact">${T.facts.map(([f,s],i)=>`<div class="row">${G(ic,pal)}<div class="tap" role="button" tabindex="0" data-sheet="mwFact" data-arg="${k}|${i}"><b>${f}</b><small>${TS.mute[k+i]?'elhallgatva · nem használja':s}</small></div><button class="mwtog ${TS.mute[k+i]?'':'on'}" data-mwmute="${k}|${i}" aria-label="${f}: ${TS.mute[k+i]?'elhallgatva':'használja'}"></button></div>`).join('')}</div></section>
  <section class="sec rise" style="--i:6"><div class="sh"><h3>Lezárt ügyei</h3></div>${T.closed.length?`<div class="card pad">${T.closed.map(([t,s])=>`<div class="row">${G('check','sage')}<div><b>${t}</b><small>${s}</small></div></div>`).join('')}</div>`:`<div class="card npempty"><img src="${PH(ph+'-sq.jpg')}" alt=""><b>Még nincs lezárt ügye</b><p>Ehhez több bejelentkezés kell.</p></div>`}</section>
  ${mzCard(T.req,k==='kozerzet'?`<button class="pill soft" data-sheet="napCheckin">Bejelentkezem</button>`:'')}</div>`}
/* ── konzílium ── */
const KZ={seg:'att',open:{0:1}};
function konzilium(){return `${ihead({ph:'mezo-asztal.jpg',crumb:'Mezo › A csapat › <b>Konzílium</b>',eb:'Vasárnap 19:30 · mind az öten',title:'Két dolog került be rólad',sub:'Egy nyugdíjazva, kettő visszadobva.',btn:`${G('book','ink')}Korábbi ülések`,attrs:'data-sheet="mwArchive"'})}
  <div class="mwseg rise" style="--i:1;margin-top:18px">${[['att','Áttekintés'],['besz','Beszélgetés']].map(([k,l])=>`<button class="${KZ.seg===k?'on':''}" data-mwkz="${k}">${l}</button>`).join('')}</div>
  ${KZ.seg==='att'?`<section class="sec rise first" style="--i:2"><div class="card trio t-sage">${[['plus','sage','+2','bekerült'],['moon','sky','1','nyugdíjazva'],['repeat','peach','2','visszadobva']].map(([ic,pal,v,l])=>`<div>${G(ic,pal)}<b>${v}</b><small>${l}</small></div>`).join('')}</div></section>
  <section class="sec rise" style="--i:3"><div class="sh"><h3>Javaslatok és döntések</h3></div><div class="mwver">${[['mezo-ejjel','A hétvégi lefekvés-minta','alvas','bekerült','soft'],['edz-ropi-blokk','Szénhidrát a meccs előtt','etkezes','bekerült','soft'],['kave','Délutáni kávé és rossz alvás','alvas','nyugdíjazva · 3 hete nem erősödik',''],['edz-sulyzotarto','Egyhangú hetek és energia','mozgas','visszadobva · kevés nap','warm'],['nap-baratok','Hétfői rossz kedv','kozerzet','visszadobva · kevés adat','warm']].map(([p,t,k,s,c])=>`<article><img src="${PH(p+'-sq.jpg')}" alt=""><div><b>${t}</b><div class="chips"><span class="chip">${nm(k)}</span><span class="chip ${c}">${s}</span></div></div></article>`).join('')}</div></section>
  <section class="sec rise" style="--i:4"><div class="sh"><h3>A Szkeptikus szólt</h3></div><div class="card pad">${[['Egyhangú hetek','Öt nap nem elég. Várjuk meg a nyolcat, mielőtt kimondjuk.'],['Hétfői rossz kedv','Ez lehet a hétvégi lefekvés hatása is. Ne számoljuk kétszer.']].map(([t,x])=>`<div class="mwc">${bd('szk')}<div><b>${t}</b><p>${x}</p></div></div>`).join('')}</div></section>`
  :[['1. forduló · javaslatok','4 javaslat',[['alvas','A hétvégi lefekvés 26 napja tartja magát. Javaslom, kerüljön be.'],['etkezes','A meccs előtti szénhidrát két meccsen működött.']]],['2. forduló · kereszt-vita','3 hozzászólás',[['mozgas','A szénhidrátnál a 4. szett ugrása is stabilabb volt, ezt megerősítem.'],['szk','Két meccs kevés. De a kísérlet fut tovább, ez rendben.']]],['3. forduló · a Szkeptikus','2 visszadobás',[['szk','Az egyhangú hetek és a hétfői kedv még nem érett meg.']]],['4. forduló · Mezo dönt','2 bekerült',[['mezo','Bekerül a lefekvés-minta és a szénhidrát. A délutáni kávét nyugdíjazom. Jövő héten a vacsora a fókusz.']]]].map(([t,s,L],i)=>`<section class="sec rise ${i?'':'first'}" style="--i:${2+i}"><div class="card mwround ${KZ.open[i]?'open':''}"><button data-mwround="${i}" aria-expanded="${!!KZ.open[i]}"><div><b>${t}</b><br><small>${s}</small></div>${G('chev','ink')}</button><div class="bd2">${L.map(([k,x])=>`<div class="mwc">${bd(k)}<div><b>${nm(k)}</b><p>${x}</p></div></div>`).join('')}</div></div></section>`).join('')}
  ${mzCard('Jövő vasárnap <em>a vacsora-ügy</em> a fókusz. Ha addig válaszolsz rá, már a te szavaddal döntünk.',`<button class="pill soft" data-go="mezo-poszt-vacsora">A vacsora-ügy</button>`)}</div>`}
/* ── kérdezd meg a csapatot + a report ── */
function kerdezd(){return `${ihead({ph:'mezo-nagyito.jpg',crumb:'Mezo › A csapat › <b>Kérdezd meg a csapatot</b>',eb:'Diagnózis · mind az öten ránéznek',title:'Mi érdekel?',sub:'Egy kérdés, és a csapat a te adataidból válaszol.'})}
  <section class="sec rise first" style="--i:2"><div class="card mwask"><textarea id="mwq" placeholder="Például: miért vagyok fáradt délutánonként?" aria-label="A kérdésed"></textarea><div class="npopt">${['Miért vagyok fáradt?','Miért alszom rosszul?','Miért nem fogyok?','Mitől jobb a kedvem?'].map(x=>`<button data-mwqx="${x}">${x}</button>`).join('')}</div><button class="pill" data-mwask>${G('search','cream')}Megkérdezem</button></div></section>
  <section class="sec rise" style="--i:3"><div class="sh"><h3>Korábbi válaszok</h3></div><div class="dlist one">${[['nap-tea','Miért vagyok fáradt?','szeptember 18. · 3 jel','mezo-riport-faradt'],['mezo-ejjel','Miért alszom rosszul hétfőn?','szeptember 8. · bekerült','mezo-riport-hetfo']].map(([p,t,s,g])=>`<article class="dl tap" role="button" tabindex="0" data-go="${g}"><span class="stk"><img src="${PH(p+'-sq.jpg')}" alt=""></span><div class="dtx"><strong>${t}</strong><div class="chips"><span class="chip">${s}</span></div></div>${G('chev','ink','chev')}</article>`).join('')}</div></section>
  ${mzCard('A válasz <em>nem diagnózis</em> orvosi értelemben: a te adataidban keresünk mintát, és megmondjuk, mennyire biztos.')}</div>`}
